/* =======================================================================
   MAXIMUM RED
   Awakened Gojo's Reversal: Red used the same hit beep as everything
   else. This is Reversal_Red_Maximum_Output_SFX_JJS from main. Fired
   as a one-shot when the wall of repulsion goes out. Apps Script
   cannot play an .mp3 URL, so the clip is carried as text.
   ===================================================================== */
(function () {
  'use strict';
  if (typeof sfx === 'undefined') return;
  window.JJRED = { ready: false, dur: 0, usedClip: 0, usedBeep: 0 };
  var RED_B64 = '';
  var redBuf = null;
  var oldHit = sfx.hit;

  function decodeRed(done) {
    if (redBuf) { done(true); return; }
    var ac = null;
    try { ac = audio(); } catch (e) {}
    if (!ac) { done(false); return; }
    try {
      var bin = atob(RED_B64);
      var bytes = new Uint8Array(bin.length), i;
      for (i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      ac.decodeAudioData(bytes.buffer.slice(0), function (buf) {
        redBuf = buf;
        try { window.JJRED.ready = true; window.JJRED.dur = buf.duration; } catch (e2) {}
        done(true);
      }, function () { done(false); });
    } catch (e) { done(false); }
  }

  function fireRed() {
    var ac = null;
    try { ac = audio(); } catch (e) {}
    if (!ac || !redBuf) return false;
    var src = ac.createBufferSource();
    var g = ac.createGain();
    g.gain.value = 1;
    src.buffer = redBuf;
    src.connect(g);
    g.connect(ac.destination);
    try { src.start(0); } catch (e) { return false; }
    return true;
  }

  sfx.redMax = function () {
    if (fireRed()) {
      try { window.JJRED.usedClip++; } catch (e) {}
      return;
    }
    decodeRed(function (ok) {
      if (ok && fireRed()) {
        try { window.JJRED.usedClip++; } catch (e) {}
      } else if (oldHit) {
        try { window.JJRED.usedBeep++; } catch (e) {}
        oldHit();
      }
    });
  };

  function arm() {
    try { audio(); } catch (e) {}
    decodeRed(function () {});
  }
  window.addEventListener('pointerdown', arm, { once: true, capture: true });
  window.addEventListener('keydown', arm, { once: true, capture: true });
  window.JJRED.play = function () { try { sfx.redMax(); } catch (e) {} };
  window.JJRED.decode = function (done) { decodeRed(done || function () {}); };
})();
